g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "impact-by-surface",
  "x": 64, "y": 175, "width": 1152, "height": 390,
  "column_widths": [150, 290, 712],
  "row_heights": [40, 40, 40, 62, 62, 62, 84],
  "header_rows": 1,
  "style": {
    "font_family": "Arial",
    "font_size": 16,
    "header_font_size": 16,
    "band_row": false,
    "header_text": "#1F2933",
    "body_text": "#1F2933",
    "valign": "top"
  },
  "defaults": {
    "cell": {
      "valign": "top",
      "align": "l",
      "padding": {"left": 12, "right": 12, "top": 8, "bottom": 8},
      "borders": {
        "left": {"style": "none"},
        "right": {"style": "none"},
        "top": {"style": "none"},
        "bottom": {"style": "solid", "color": "#D7DDE3", "width": 1}
      }
    },
    "run": {"color": "#1F2933"}
  },
  "cell_styles": {
    "header": {
      "bold": true,
      "align": "l",
      "borders": {
        "left": {"style": "none"},
        "right": {"style": "none"},
        "top": {"style": "none"},
        "bottom": {"style": "solid", "color": "#1F2933", "width": 2}
      }
    }
  },
  "columns": [
    {"text": "Severity", "cell_style": "header"},
    {"text": "Service or product", "cell_style": "header"},
    {"text": "Impact as published", "cell_style": "header"}
  ],
  "rows": [
    [
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"text": "Core CDN and security services", "bold": true},
      {"text": "HTTP 5xx status codes returned to end users."}
    ],
    [
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"text": "Turnstile", "bold": true},
      {"text": "Turnstile failed to load."}
    ],
    [
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"text": "Workers KV", "bold": true},
      {"paragraphs": ["Significantly elevated HTTP 5xx errors, as requests to the KV", "front-end gateway failed with the core proxy."]}
    ],
    [
      {"text": "Critical", "fill": "#F7E4E2", "bold": true},
      {"text": "Access", "bold": true},
      {"paragraphs": ["Widespread authentication failures until the rollback was initiated", "at 13:05; existing sessions unaffected, failed attempts returned an error page."]}
    ],
    [
      {"text": "Degraded", "fill": "#FAF0DC", "bold": true},
      {"text": "Dashboard", "bold": true},
      {"paragraphs": ["Mostly operational, but most users could not log in because", "Turnstile was unavailable on the login page."]}
    ],
    [
      {"text": "Degraded", "fill": "#FAF0DC", "bold": true},
      {"text": "Email Security", "bold": true},
      {"paragraphs": ["Processing and delivery unaffected. Temporary loss of an IP reputation", "source reduced spam-detection accuracy and prevented some new-domain-age", "detections; some Auto Move actions failed, all reviewed and remediated."]}
    ]
  ]
}
